import org.springframework.security.core.Authentication;
import org.springframework.security.core.context.SecurityContext;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class AuditController {

    @GetMapping("/api/current-user")
    public String getCurrentUserPrincipal() {
        // Accessing the SecurityContext from the SecurityContextHolder's ThreadLocal strategy
        SecurityContext context = SecurityContextHolder.getContext();
        Authentication authentication = context.getAuthentication();

        if (authentication == null || !authentication.isAuthenticated()) {
            return "Anonymous";
        }

        // The principal is typically a UserDetails implementation or a String (username)
        return "Authenticated User: " + authentication.getName() + 
               " with authorities: " + authentication.getAuthorities();
    }
}
